<section class="section-wrap dashboard-page admin-page"><div class="dashboard-heading"><div><p class="eyebrow">YOUR COLLECTION</p><h1>Products<span class="brand-dot">.</span></h1><p>Keep your Shifa edit fresh and thoughtful.</p></div><a class="button button-dark" href="<?= $e($base) ?>/admin/product">Add a product <span>＋</span></a></div><div class="data-card"><div class="table-head products-admin-head"><span>Product</span><span>Category</span><span>Price</span><span>Stock</span><span>Visibility</span><span></span></div><?php foreach ($products as $product): ?><div class="table-row products-admin-head"><b><?= $e($product['name']) ?></b><span><?= $e($product['category_name'] ?? '—') ?></span><span><?= number_format((float) $product['price'], 2) ?> JOD</span><span><?= (int) $product['stock'] ?></span><span><i class="status-pill <?= (int) $product['is_active'] ? 'status-live' : 'status-cancelled' ?>"><?= (int) $product['is_active'] ? 'Live' : 'Hidden' ?></i></span><span class="row-actions"><a href="<?= $e($base) ?>/admin/product?id=<?= (int) $product['id'] ?>">Edit</a><form action="<?= $e($base) ?>/admin/product/delete" method="post" onsubmit="return confirm('Hide this product from the shop?')"><input type="hidden" name="csrf_token" value="<?= $e($csrf_token) ?>"><input type="hidden" name="id" value="<?= (int) $product['id'] ?>"><button>Hide</button></form></span></div><?php endforeach; ?><?php if (!$products): ?><p class="empty-inline">Your collection is ready for its first product.</p><?php endif; ?></div></section>
